var r=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.ExcavationRounds>();var s=r.equipment.Snapshot;var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None);s.depletedBlocks=rocks.Select(x=>x.blockId).ToArray();s.items=System.Array.Empty<int>();s.groundDrops=System.Array.Empty<Bulldozer.Player.Persistence.GroundOreState>();r.equipment.Commit(s);r.Evaluate();
var report=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,msg)=>report.Add((ok?"PASS ":"FAIL ")+msg);check(r.equipment.Cash==340&&r.equipment.Snapshot.roundBonusClaimed,"Second round awards $60 once");int old=r.GetInstanceID();r.NextRound();r.NextRound();int start=Time.frameCount;EditorApplication.isPaused=true;Time.captureDeltaTime=1f/30;EditorApplication.CallbackFunction tick=null;tick=()=>{if(!EditorApplication.isPlaying){EditorApplication.update-=tick;return;}var fresh=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.ExcavationRounds>();if(fresh&&fresh.GetInstanceID()!=old&&Time.frameCount>start+60){var e=fresh.equipment;check(fresh.RoundNumber==3&&e.Cash==340,"Second transition reaches third excavation without resetting cash");check(e.DamageLevel==1&&e.CapacityLevel==2&&e.SpeedLevel==1&&e.Snapshot.wheelbarrowUnlocked,"Equipment and upgrades survive repeated transitions");check(UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None).Count(x=>!x.Depleted)==78,"Third round restores same fixed rock pool");check(UnityEngine.Object.FindObjectsByType<MoreMountains.Feedbacks.MMF_Player>(FindObjectsSortMode.None).Length==2,"Feel player count stays fixed across rounds");check(fresh.player.GetComponent<CharacterController>().enabled&&!fresh.player.InputBlocked,"Player remains controllable after repeated reloads");System.IO.File.WriteAllLines("Maintenance/Miner/excavation-repeat-verification.txt",report);EditorApplication.update-=tick;Time.captureDeltaTime=0;return;}if(Time.frameCount-start>600){System.IO.File.WriteAllText("Maintenance/Miner/excavation-repeat-verification.txt","FAIL Transition timeout");EditorApplication.update-=tick;Time.captureDeltaTime=0;return;}EditorApplication.Step();};EditorApplication.update+=tick;return "Testing second completion and third excavation";
